#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
typedef struct DiagnosticPayload {
    uint32_t id;
    uint64_t timestamp;
    uint8_t data_buffer[8];
} DiagnosticPayload;

#include "native_engine.h" // Automatically generated by the Zeus compiler

int main() {
    size_t count = 50000000; // 50 Million Frames
    DiagnosticPayload* stream = (DiagnosticPayload*)calloc(count, sizeof(DiagnosticPayload));
    
    // Seed some anomalies
    stream[count / 2].data_buffer[0] = 0xFF;
    stream[count - 1].data_buffer[0] = 0xFF;

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    
    // Legacy code handles the setup, but Zeus does the heavy lifting instantly
    uint32_t alerts = zeus_process_stream((void*)stream, count);
    
    clock_gettime(CLOCK_MONOTONIC, &end);
    double time_taken = (end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) / 1e3;
    
    printf("Zeus processed 50M frames. Alerts found: %u\n", alerts);
    printf("Time taken: %.2f microseconds\n", time_taken);

    free(stream);
    return 0;
}
